class SocialRobot:
    def __init__(self):
        self.facial_recognizer = FacialExpressionRecognizer()
        self.voice_analyzer = VoiceEmotionAnalyzer()
        self.emotional_expressor = EmotionalExpressionSystem()
        self.social_engine = SocialBehaviorEngine()

        self.current_human_emotion = 'neutral'
        self.current_confidence = 0.0
        self.interaction_history = []

    def perceive_human_emotion(self, frame: np.ndarray, audio_data: np.ndarray = None) -> Dict:
        """Perceive human emotion from multiple modalities"""
        emotion_perception = {
            'facial_emotion': None,
            'voice_emotion': None,
            'combined_emotion': 'neutral',
            'confidence': 0.0
        }

        # Analyze facial expression
        faces = self.facial_recognizer.detect_faces(frame)
        if len(faces) > 0:
            # Use the first detected face
            x, y, w, h = faces[0]
            face_roi = frame[y:y+h, x:x+w]
            facial_emotion, facial_conf = self.facial_recognizer.recognize_emotion(face_roi)
            emotion_perception['facial_emotion'] = facial_emotion
            emotion_perception['facial_confidence'] = facial_conf

        # Analyze voice emotion if available
        if audio_data is not None:
            voice_emotion, voice_conf = self.voice_analyzer.analyze_emotion_from_voice(audio_data)
            emotion_perception['voice_emotion'] = voice_emotion
            emotion_perception['voice_confidence'] = voice_conf

        # Combine modalities (simplified approach)
        if emotion_perception['facial_emotion'] and emotion_perception['voice_emotion']:
            # If both modalities agree, higher confidence
            if emotion_perception['facial_emotion'] == emotion_perception['voice_emotion']:
                emotion_perception['combined_emotion'] = emotion_perception['facial_emotion']
                emotion_perception['confidence'] = (emotion_perception['facial_conf'] + emotion_perception['voice_conf']) / 2 * 1.2
            else:
                # If they disagree, use facial emotion (often more reliable for basic emotions)
                emotion_perception['combined_emotion'] = emotion_perception['facial_emotion']
                emotion_perception['confidence'] = (emotion_perception['facial_conf'] + emotion_perception['voice_conf']) / 2
        elif emotion_perception['facial_emotion']:
            emotion_perception['combined_emotion'] = emotion_perception['facial_emotion']
            emotion_perception['confidence'] = emotion_perception['facial_confidence']
        elif emotion_perception['voice_emotion']:
            emotion_perception['combined_emotion'] = emotion_perception['voice_emotion']
            emotion_perception['confidence'] = emotion_perception['voice_confidence']

        # Ensure confidence is in [0, 1]
        emotion_perception['confidence'] = min(max(emotion_perception['confidence'], 0.0), 1.0)

        # Update internal state
        self.current_human_emotion = emotion_perception['combined_emotion']
        self.current_confidence = emotion_perception['confidence']

        return emotion_perception

    def respond_to_human(self, human_state: Dict, context: Dict = None) -> Dict:
        """Generate appropriate social response to human"""
        if context is None:
            context = {'relationship': 'acquaintance', 'formality': 'casual'}

        # Generate emotional response
        emotional_response = self.emotional_expressor.generate_emotional_response(
            self.current_human_emotion, self.current_confidence, context.get('formality', 'casual')
        )

        # Determine appropriate social behavior
        social_behavior = self.social_engine.determine_appropriate_behavior(human_state, context)

        # Combine responses
        response = {
            'emotional_response': emotional_response,
            'social_behavior': social_behavior,
            'action_plan': self._create_action_plan(emotional_response, social_behavior)
        }

        # Add to interaction history
        self.interaction_history.append({
            'timestamp': time.time(),
            'human_emotion': self.current_human_emotion,
            'response': response
        })

        return response

    def _create_action_plan(self, emotional_response: Dict, social_behavior: Dict) -> List[Dict]:
        """Create an action plan based on emotional and social responses"""
        actions = []

        # Add facial expression action
        if emotional_response['facial_expression'] != 'neutral':
            actions.append({
                'type': 'facial_expression',
                'expression': emotional_response['facial_expression'],
                'intensity': emotional_response['intensity']
            })

        # Add vocal response if needed
        if emotional_response['vocal_tone'] != 'neutral':
            actions.append({
                'type': 'vocal_response',
                'tone': emotional_response['vocal_tone'],
                'content': self._generate_response_text()
            })

        # Add body language action
        if social_behavior['engagement_level'] in ['high', 'supportive']:
            actions.append({
                'type': 'body_language',
                'gesture': emotional_response['body_language'],
                'intensity': emotional_response['intensity']
            })

        return actions

    def _generate_response_text(self) -> str:
        """Generate appropriate response text based on detected emotion"""
        if self.current_human_emotion == 'happy':
            return "That's wonderful! I'm glad you're happy."
        elif self.current_human_emotion == 'sad':
            return "I'm sorry you're feeling down. How can I help?"
        elif self.current_human_emotion == 'angry':
            return "I understand you're upset. Let me see how I can assist."
        elif self.current_human_emotion == 'surprised':
            return "Oh, that's surprising! Tell me more about it."
        else:
            return "Hello! How are you doing today?"

    def generate_capability_explanation(self, capability: str, success_rate: float) -> str:
        """Explain a specific capability and its reliability"""
        if success_rate > 0.9:
            reliability = "very reliable"
        elif success_rate > 0.7:
            reliability = "generally reliable"
        elif success_rate > 0.5:
            reliability = "somewhat reliable"
        else:
            reliability = "not very reliable"

        explanation = f"My {capability} capability is {reliability}. I succeed about {int(success_rate * 100)}% of the time."

        if success_rate < 0.7:
            explanation += f" For important tasks involving {capability}, you might want to double-check my results."

        return explanation

class CapabilityCommunicator:
    def __init__(self):
        self.capabilities = {
            'navigation': {'success_rate': 0.85, 'conditions': 'indoor, structured environments'},
            'object_recognition': {'success_rate': 0.78, 'conditions': 'well-lit, common objects'},
            'speech_recognition': {'success_rate': 0.82, 'conditions': 'quiet environments'},
            'grasping': {'success_rate': 0.75, 'conditions': 'medium-sized objects, stable surfaces'},
            'conversation': {'success_rate': 0.70, 'conditions': 'simple topics, clear speech'}
        }

    def get_capability_status(self, robot_state: Dict = None) -> Dict:
        """Get current status of robot capabilities"""
        status = {}
        for capability, info in self.capabilities.items():
            status[capability] = {
                'success_rate': info['success_rate'],
                'conditions': info['conditions'],
                'current_limitations': self._get_current_limitations(capability, robot_state)
            }
        return status

    def _get_current_limitations(self, capability: str, robot_state: Dict) -> List[str]:
        """Get current limitations for a specific capability"""
        limitations = []

        if robot_state:
            # Check environment conditions
            if capability == 'object_recognition' and robot_state.get('lighting', 'good') == 'poor':
                limitations.append('Recognition accuracy may be reduced in low light')
            elif capability == 'speech_recognition' and robot_state.get('noise_level', 'low') == 'high':
                limitations.append('Speech recognition may be affected by background noise')
            elif capability == 'navigation' and robot_state.get('floor_type', 'flat') in ['uneven', 'stairs']:
                limitations.append('Navigation may be challenging on uneven terrain')

        return limitations

    def generate_capability_report(self) -> str:
        """Generate a human-readable report of capabilities"""
        report = "My current capabilities include:\n"
        for capability, info in self.capabilities.items():
            report += f"- {capability}: {info['success_rate']:.0%} success rate ({info['conditions']})\n"

        report += "\nI will let you know if any of these capabilities are affected by current conditions."
        return report

class TrustDynamicsSimulator:
    def __init__(self):
        self.trust_builder = RobotTrustBuilder()
        self.trust_measurement = self.trust_builder.trust_measurement
        self.interaction_history = []

    def simulate_interaction(self, user_profile: Dict, robot_actions: List[Dict]) -> Dict:
        """Simulate an interaction and track trust changes"""
        interaction_result = {
            'initial_trust': self.trust_measurement.trust_score,
            'actions_taken': robot_actions,
            'trust_changes': [],
            'final_trust': None
        }

        for action in robot_actions:
            # Process action and update trust indicators
            self._process_action(action, user_profile)

            # Record trust change
            interaction_result['trust_changes'].append({
                'action': action,
                'trust_score': self.trust_measurement.trust_score,
                'timestamp': time.time()
            })

        interaction_result['final_trust'] = self.trust_measurement.trust_score
        self.interaction_history.append(interaction_result)

        return interaction_result

    def _process_action(self, action: Dict, user_profile: Dict):
        """Process a robot action and update trust indicators"""
        action_type = action.get('type', 'unknown')

        if action_type == 'provide_explanation':
            # Providing explanations generally increases trust
            self.trust_measurement.trust_indicators['user_compliance'] += 0.05
        elif action_type == 'communicate_capabilities':
            # Clear communication of capabilities increases trust
            self.trust_measurement.trust_indicators['user_compliance'] += 0.03
        elif action_type == 'adjust_communication_style':
            # Personalization can increase trust
            self.trust_measurement.trust_indicators['interaction_duration'] += 0.1

        # Update overall trust score
        self.trust_measurement.trust_score = self.trust_measurement._calculate_trust_score()

        # Log the action
        self.trust_measurement.log_interaction('robot_action', action)

    def _check_privacy(self, action: Dict, user_context: Dict) -> float:
        """Check if action protects privacy"""
        # Consider data collection and sharing
        if action.get('type') == 'collect_data':
            consent = action.get('consent_obtained', False)
            data_type = action.get('data_type', 'general')
            if consent and data_type == 'general':
                return 0.8
            elif consent and data_type in ['sensitive', 'biometric']:
                return 0.6  # Even with consent, sensitive data is risky
            else:
                return 0.1
        elif action.get('type') == 'share_information':
            permission = action.get('permission_granted', False)
            if permission:
                return 0.8
            else:
                return 0.1
        else:
            return 0.9  # No privacy concern

class BiasDetectionSystem:
    def __init__(self):
        self.bias_detection_rules = {
            'gender_bias': self._detect_gender_bias,
            'cultural_bias': self._detect_cultural_bias,
            'age_bias': self._detect_age_bias,
            'ability_bias': self._detect_ability_bias
        }
        self.bias_threshold = 0.7  # Above this is considered biased
        self.detection_history = []

    def detect_bias(self, interaction_data: Dict) -> Dict:
        """Detect potential biases in robot interaction"""
        bias_analysis = {
            'gender_bias': 0.0,
            'cultural_bias': 0.0,
            'age_bias': 0.0,
            'ability_bias': 0.0,
            'overall_bias_score': 0.0,
            'recommendations': []
        }

        for bias_type, detection_func in self.bias_detection_rules.items():
            score = detection_func(interaction_data)
            bias_analysis[bias_type] = score

        # Calculate overall bias score
        bias_analysis['overall_bias_score'] = np.mean(list(bias_analysis.values())[:4])

        # Generate recommendations for high bias scores
        for bias_type, score in bias_analysis.items():
            if bias_type != 'overall_bias_score' and score > self.bias_threshold:
                bias_analysis['recommendations'].append(
                    f"Potential {bias_type.replace('_', ' ')} detected. Consider reviewing {bias_type.replace('_', ' ')} sensitivity in robot responses."
                )

        # Add to history
        self.detection_history.append({
            'timestamp': time.time(),
            'analysis': bias_analysis.copy(),
            'interaction_data': interaction_data
        })

        return bias_analysis

    def _detect_gender_bias(self, interaction_data: Dict) -> float:
        """Detect potential gender bias in interactions"""
        # Check for differential treatment based on perceived gender
        user_gender = interaction_data.get('user_gender', 'unknown')
        if user_gender == 'unknown':
            return 0.1  # Low confidence in detection

