class BehaviorArbitrator:
    """Arbitrates between competing behavior outputs"""
    def __init__(self):
        self.conflict_resolution_strategy = "priority"

    def select_action(self, behavior_outputs: List[Tuple[int, Dict[str, Any]]]) -> Dict[str, Any]:
        """Select action based on behavior outputs"""
        if not behavior_outputs:
            return {"linear_velocity": 0.0, "angular_velocity": 0.0}

        if self.conflict_resolution_strategy == "priority":
            # Select behavior with highest priority
            highest_priority = max(behavior_outputs, key=lambda x: x[0])
            return highest_priority[1]
        else:
            # Weighted combination approach
            linear_vel = 0.0
            angular_vel = 0.0
            total_weight = 0.0

            for priority, output in behavior_outputs:
                weight = priority  # Use priority as weight
                linear_vel += output.get("linear_velocity", 0.0) * weight
                angular_vel += output.get("angular_velocity", 0.0) * weight
                total_weight += weight

            if total_weight > 0:
                linear_vel /= total_weight
                angular_vel /= total_weight

            return {
                "linear_velocity": linear_vel,
                "angular_velocity": angular_vel
            }

        while queue:
            current, path = queue.pop(0)
            if len(path) > max_depth:
                continue

            if current == end_concept:
                return path

            visited.add(current)

            # Check all relationships from current concept
            if current in self.concepts:
                concept = self.concepts[current]
                for rel_type, related_concepts in concept.relationships.items():
                    for related in related_concepts:
                        if related not in visited:
                            new_path = path + [related]
                            queue.append((related, new_path))

        return []  # No path found

    def update_concept(self, name: str, properties: Dict[str, Any] = None,
                      relationships: Dict[str, List[str]] = None) -> bool:
        """Update an existing concept"""
        if name not in self.concepts:
            return False

        concept = self.concepts[name]
        concept.last_accessed = time.time()

        if properties:
            concept.properties.update(properties)

        if relationships:
            for rel_type, related_concepts in relationships.items():
                if rel_type in concept.relationships:
                    concept.relationships[rel_type].extend(related_concepts)
                else:
                    concept.relationships[rel_type] = related_concepts

        return True

class WorkingMemory:
    """Working memory for active information processing"""
    def __init__(self, capacity: int = 100):
        self.capacity = capacity
        self.items: Dict[str, Tuple[Any, float]] = {}  # item_id -> (content, timestamp)
        self.attention_weights: Dict[str, float] = {}  # item_id -> attention weight
        self.context: Dict[str, Any] = {}  # Current context information

    def add(self, item_id: str, content: Any, attention: float = 1.0):
        """Add an item to working memory"""
        timestamp = time.time()
        self.items[item_id] = (content, timestamp)
        self.attention_weights[item_id] = attention

        # Manage capacity
        if len(self.items) > self.capacity:
            self._remove_lowest_priority()

    def get(self, item_id: str) -> Optional[Any]:
        """Retrieve an item from working memory"""
        if item_id in self.items:
            content, timestamp = self.items[item_id]
            # Update timestamp (recent access)
            self.items[item_id] = (content, time.time())
            return content
        return None

    def get_all(self) -> Dict[str, Any]:
        """Get all items in working memory"""
        return {k: v[0] for k, v in self.items.items()}

    def update_attention(self, item_id: str, attention: float):
        """Update attention weight for an item"""
        if item_id in self.attention_weights:
            self.attention_weights[item_id] = attention

    def decay_memory(self, decay_rate: float = 0.01):
        """Apply decay to memory items based on time"""
        current_time = time.time()
        items_to_remove = []

        for item_id, (content, timestamp) in self.items.items():
            time_diff = current_time - timestamp
            if time_diff > 3600:  # Remove items older than 1 hour
                items_to_remove.append(item_id)

        for item_id in items_to_remove:
            self.remove(item_id)

    def remove(self, item_id: str):
        """Remove an item from working memory"""
        if item_id in self.items:
            del self.items[item_id]
        if item_id in self.attention_weights:
            del self.attention_weights[item_id]

    def _remove_lowest_priority(self):
        """Remove the lowest priority item to manage capacity"""
        if not self.items:
            return

        # Remove item with lowest attention weight
        lowest_priority = min(self.attention_weights.items(), key=lambda x: x[1])
        self.remove(lowest_priority[0])

    def set_context(self, key: str, value: Any):
        """Set context information"""
        self.context[key] = value

    def get_context(self, key: str, default: Any = None) -> Any:
        """Get context information"""
        return self.context.get(key, default)

class MemoryConsolidationSystem:
    """System for consolidating memories between different memory types"""
    def __init__(self, episodic_memory: EpisodicMemory, semantic_memory: SemanticMemory):
        self.episodic_memory = episodic_memory
        self.semantic_memory = semantic_memory
        self.consolidation_threshold = 0.7
        self.importance_decay_rate = 0.95

    def consolidate_episode_to_semantic(self, episode_id: str):
        """Consolidate relevant information from episodic to semantic memory"""
        if episode_id not in self.episodic_memory.episodes:
            return False

        episode = self.episodic_memory.episodes[episode_id]

        # Extract potential concepts from episode content
        for key, value in episode.content.items():
            if isinstance(value, (str, int, float)) and len(str(value)) > 2:
                # Check if this represents a concept worth storing semantically
                concept_name = f"{key}_{value}".replace(" ", "_").replace("-", "_")

                # Check if concept already exists
                if concept_name not in self.semantic_memory.concepts:
                    properties = {key: value, "source_episodes": [episode_id]}
                    self.semantic_memory.store_concept(concept_name, properties=properties)

        # Execute next action if available
        if not self.action_queue.empty():
            try:
                action = self.action_queue.get_nowait()
                execution_result = self._execute_action(action)
                outputs['action_result'] = execution_result
                self.executed_actions.append({
                    'action': action,
                    'result': execution_result,
                    'timestamp': time.time()
                })
            except queue.Empty:
                pass

        return outputs

    def _execute_action(self, action: Dict[str, Any]) -> Dict[str, Any]:
        """Execute a specific action"""
        action_type = action.get('action', 'unknown')

        # Simulate action execution
        if action_type in ['move_to', 'approach_object']:
            return {'status': 'success', 'position': action.get('target', (0, 0))}
        elif action_type in ['grasp', 'release']:
            return {'status': 'success', 'object': action.get('object', 'unknown')}
        elif action_type == 'orient_to':
            return {'status': 'success', 'orientation': action.get('target', 0)}
        else:
            return {'status': 'unknown_action'}

class Blackboard:
    """Shared workspace for cognitive modules"""
    def __init__(self):
        self.data_spaces: Dict[str, Any] = {}
        self.module_access_log: Dict[str, List[str]] = defaultdict(list)
        self.data_lock = threading.Lock()
        self.subscribers: Dict[str, List[Callable]] = defaultdict(list)

    def write(self, space: str, key: str, value: Any):
        """Write data to a specific space on the blackboard"""
        with self.data_lock:
            if space not in self.data_spaces:
                self.data_spaces[space] = {}
            self.data_spaces[space][key] = value

            # Notify subscribers
            for callback in self.subscribers.get(f"{space}.{key}", []):
                try:
                    callback(key, value)
                except Exception as e:
                    print(f"Error in blackboard subscriber: {e}")

    def read(self, space: str, key: str, default: Any = None) -> Any:
        """Read data from a specific space on the blackboard"""
        with self.data_lock:
            if space in self.data_spaces and key in self.data_spaces[space]:
                return self.data_spaces[space][key]
            return default

    def subscribe(self, space: str, key: str, callback: Callable):
        """Subscribe to changes in a specific blackboard location"""
        self.subscribers[f"{space}.{key}"].append(callback)

    def get_space(self, space: str) -> Dict[str, Any]:
        """Get all data from a specific space"""
        with self.data_lock:
            return self.data_spaces.get(space, {}).copy()

    def update_module_access(self, module_name: str, space: str, operation: str):
        """Log module access to blackboard spaces"""
        self.module_access_log[module_name].append(f"{operation} to {space}")

class ExecutiveController:
    """Executive control system for coordinating cognitive modules"""
    def __init__(self):
        self.modules: Dict[str, CognitiveModule] = {}
        self.module_priorities: Dict[str, int] = {}
        self.active_modules: List[str] = []
        self.goals: List[Dict[str, Any]] = []
        self.interrupt_threshold = 0.8
        self.execution_cycle = 0.1  # 100ms between cycles

        # Module activation policies
        self.activation_policies = {
            'perception': self._should_activate_perception,
            'memory': self._should_activate_memory,
            'reasoning': self._should_activate_reasoning,
            'planning': self._should_activate_planning,
            'action_selection': self._should_activate_action_selection
        }

    def register_module(self, module: CognitiveModule):
        """Register a cognitive module with the executive controller"""
        self.modules[module.name] = module
        self.module_priorities[module.name] = module.priority
        self.active_modules.append(module.name)

    def add_goal(self, goal: Dict[str, Any]):
        """Add a goal for the system to achieve"""
        self.goals.append(goal)

    def run_cycle(self, external_inputs: Dict[str, Any] = None) -> Dict[str, Any]:
        """Run one cycle of executive control"""
        if external_inputs is None:
            external_inputs = {}

        cycle_outputs = {}

        # Determine which modules should be active this cycle
        active_modules = self._determine_active_modules()

        # Execute modules in priority order
        for module_name in sorted(active_modules, key=lambda x: self.module_priorities.get(x, 0), reverse=True):
            if module_name in self.modules:
                module = self.modules[module_name]

                # Prepare inputs for the module
                module_inputs = self._prepare_module_inputs(module_name, external_inputs, cycle_outputs)

                # Execute the module
                try:
                    module_outputs = module.execute(module_inputs)
                    cycle_outputs[module_name] = module_outputs

                    # Check for high-priority interrupts
                    if self._should_interrupt(module_name, module_outputs):
                        break

                except Exception as e:
                    print(f"Error executing module {module_name}: {e}")

        return cycle_outputs

    def _determine_active_modules(self) -> List[str]:
        """Determine which modules should be active based on goals and priorities"""
        # For now, return all active modules
        # In a more sophisticated system, this would consider current goals,
        # resource constraints, and module dependencies
        return self.active_modules

        return self.attention_spans[0]  # Highest priority focus

    def get_attention_distribution(self) -> Dict[str, float]:
        """Get distribution of attention across modalities"""
        distribution = defaultdict(float)

        for focus in self.attention_spans:
            distribution[focus.modality] += focus.priority * focus.task_relevance

        # Normalize to sum to 1
        total = sum(distribution.values())
        if total > 0:
            for modality in distribution:
                distribution[modality] /= total

        return dict(distribution)

class SelectiveProcessor:
    """Processes information selectively based on attention"""
    def __init__(self, attention_controller: AttentionController):
        self.attention_controller = attention_controller
        self.processing_history = deque(maxlen=100)
        self.attention_gates = {}  # Modality -> processing function

    def register_processing_module(self, modality: str, processing_func):
        """Register a processing function for a specific modality"""
        self.attention_gates[modality] = processing_func

    def process_input_selectively(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        """Process input selectively based on current attention"""
        # Get current attention distribution
        attention_dist = self.attention_controller.get_attention_distribution()

        results = {}

        # Process each modality according to its attention weight
        for modality, data in input_data.items():
            attention_weight = attention_dist.get(modality, 0.0)

            if attention_weight > 0.1:  # Only process if attention is above threshold
                if modality in self.attention_gates:
                    # Process with attention-weighted intensity
                    processed_result = self.attention_gates[modality](data, attention_weight)
                    results[modality] = processed_result
                else:
                    # Default processing - just pass through with attention weight
                    results[modality] = {
                        'data': data,
                        'attention_weight': attention_weight,
                        'processed': False
                    }

        # Log processing for history
        self.processing_history.append({
            'timestamp': time.time(),
            'input_modalities': list(input_data.keys()),
            'attention_weights': attention_dist,
            'results': list(results.keys())
        })

        return results

    def get_processing_efficiency(self) -> float:
        """Calculate processing efficiency based on selective attention"""
        if not self.processing_history:
            return 0.0

        # Calculate efficiency as the inverse of average attention distribution
        # (More focused attention = higher efficiency)
        total_entropy = 0.0
        for record in list(self.processing_history)[-10:]:  # Last 10 records
            weights = list(record['attention_weights'].values())
            if weights:
                # Calculate entropy of attention distribution
                entropy = -sum(w * np.log2(w + 1e-6) for w in weights if w > 0)
                total_entropy += entropy

        avg_entropy = total_entropy / min(len(self.processing_history), 10) if self.processing_history else 0

        # Convert entropy to efficiency (lower entropy = higher efficiency)
        efficiency = max(0.0, 1.0 - avg_entropy / np.log2(len(self.attention_gates) + 1))
        return efficiency

